#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define ROWS 5
#define COLS 6

static const int dr[4] = { -1, 1, 0, 0 };
static const int dc[4] = {  0, 0,-1, 1 };

int main(int argc, char *argv[])
{
    if (argc != 5) {
        puts("INVALID_CELL");
        return 0;
    }

    long sr = strtol(argv[1], NULL, 10);
    long sc = strtol(argv[2], NULL, 10);
    long tr = strtol(argv[3], NULL, 10);
    long tc = strtol(argv[4], NULL, 10);

    if (sr < 0 || sr >= ROWS || sc < 0 || sc >= COLS ||
        tr < 0 || tr >= ROWS || tc < 0 || tc >= COLS) {
        puts("INVALID_CELL");
        return 0;
    }

    char grid[ROWS][COLS + 1];
    for (int r = 0; r < ROWS; ++r) {
        if (!fgets(grid[r], sizeof(grid[r]), stdin)) {
            puts("INVALID_CELL");
            return 0;
        }
        size_t len = strlen(grid[r]);
        if (len && grid[r][len - 1] == '\n')
            grid[r][len - 1] = '\0';
        while (strlen(grid[r]) < COLS)
            grid[r][strlen(grid[r])] = '.';
        grid[r][COLS] = '\0';
    }

    if (grid[sr][sc] == '#') {
        puts("INVALID_CELL");
        return 0;
    }

    bool visited[ROWS][COLS] = { { false } };
    int  dist[ROWS][COLS]    = { { 0 } };
    int  q_row[ROWS * COLS];
    int  q_col[ROWS * COLS];
    int head = 0, tail = 0;

    visited[sr][sc] = true;
    dist[sr][sc]    = 0;
    q_row[tail] = (int)sr;
    q_col[tail] = (int)sc;
    ++tail;

    while (head < tail) {
        int r = q_row[head];
        int c = q_col[head];
        ++head;

        if (r == tr && c == tc) {
            printf("dist=%d\n", dist[r][c]);
            return 0;
        }

        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS)
                continue;
            if (grid[nr][nc] == '#')
                continue;
            if (visited[nr][nc])
                continue;
            visited[nr][nc] = true;
            dist[nr][nc]    = dist[r][c] + 1;
            q_row[tail] = nr;
            q_col[tail] = nc;
            ++tail;
        }
    }

    puts("UNREACHABLE");
    return 0;
}
